t.script:
(function() {
    var STORAGE_KEY = 'misa_sale_status_code';
    var PAGE_SIZE = 50;
    var COLORS = {missing: '#d03b3b', requested: '#fab219', exception: '#9a9992', invoiced: '#0ca30c'};
    var STATE_META = [
        {key: 'missing', label: 'Chưa có đề nghị'},
        {key: 'requested', label: 'Đã đề nghị, chờ HĐ'},
        {key: 'exception', label: 'Ngoại lệ'},
        {key: 'invoiced', label: 'Đã xuất HĐ'},
    ];
    var state = {
        salerCode: localStorage.getItem(STORAGE_KEY) || '',
        search: '', stateFilter: '', dateFrom: '', dateTo: '',
        multiOrderGroup: false, multiRequest: false,
        page: 1, total: 0, rows: [], selected: {},
        activeTab: 'pickings',
        shopee: {search: '', stateFilter: '', page: 1, total: 0, rows: [], loaded: false},
        customs: {search: '', page: 1, total: 0, rows: [], loaded: false, preview: null, pendingOnly: false, pendingCount: 0},
    };

    function esc(s) {
        var d = document.createElement('div');
        d.textContent = s == null ? '' : String(s);
        return d.innerHTML;
    }
    function fmtMoney(n) {
        if (!n) { return '0 đ'; }
        return Math.round(n).toLocaleString('vi-VN') + ' đ';
    }
    function fmtCompactMoney(n) {
        n = n || 0;
        if (Math.abs(n) >= 1000000) { return (n / 1000000).toFixed(1).replace(/\.0$/, '') + 'tr'; }
        if (Math.abs(n) >= 1000) { return Math.round(n / 1000) + 'k'; }
        return String(Math.round(n));
    }
    function rpc(url, params) {
        return fetch(url, {
            method: 'POST', headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: params || {}}),
        }).then(function(r) { return r.json(); }).then(function(j) {
            if (j.error) {
                var msg = (j.error.data && j.error.data.message) || j.error.message || 'Có lỗi xảy ra';
                throw new Error(msg);
            }
            if (j.result && j.result.status === 'error') {
                throw new Error(j.result.message || 'Có lỗi xảy ra');
            }
            return j.result;
        });
    }
    function toast(message, type) {
        var stack = document.getElementById('msu-toast-stack');
        var el = document.createElement('div');
        el.className = 'msu-toast' + (type ? ' ' + type : '');
        el.textContent = message;
        stack.appendChild(el);
        setTimeout(function() { el.remove(); }, 5000);
    }

    // Vô hiệu hóa + đổi sang icon xoay trong lúc chờ RPC (gọi MISA có thể mất
    // vài giây) — để người dùng biết đang xử lý, tránh bấm lặp lại nhiều lần.
    // data-loading-text (nếu có trên nút) sẽ hiện kèm chữ, không có thì chỉ hiện icon.
    function setBtnLoading(btn, loading) {
        if (!btn) { return; }
        if (loading) {
            if (btn.dataset.loading === '1') { return; }
            btn.dataset.loading = '1';
            btn.dataset.originalHtml = btn.innerHTML;
            var loadingText = btn.dataset.loadingText;
            btn.innerHTML = '<i class="fa fa-spinner fa-spin"></i>' + (loadingText ? ' ' + esc(loadingText) : '');
            btn.disabled = true;
        } else {
            if (btn.dataset.loading !== '1') { return; }
            btn.innerHTML = btn.dataset.originalHtml;
            btn.disabled = false;
            delete btn.dataset.loading;
        }
    }

    var selectEl = document.getElementById('msu-saler-select');
    var appEl = document.getElementById('msu-app');
    var hintEl = document.getElementById('msu-identity-hint');

    function loadSalerCodes() {
        return rpc('/misa_sale_status/api/saler_codes').then(function(res) {
            var codes = res.codes || [];
            codes.forEach(function(code) {
                var opt = document.createElement('option');
                opt.value = code;
                opt.textContent = code;
                selectEl.appendChild(opt);
            });
            if (state.salerCode && codes.indexOf(state.salerCode) !== -1) {
                selectEl.value = state.salerCode;
                onSalerChosen();
            } else if (state.salerCode) {
                hintEl.textContent = 'Mã "' + state.salerCode + '" đã lưu trước đó không còn hợp lệ, vui lòng chọn lại.';
                state.salerCode = '';
                localStorage.removeItem(STORAGE_KEY);
            }
        }).catch(function(e) { toast('Lỗi tải danh sách mã sale: ' + e.message, 'error'); });
    }

    function onSalerChosen() {
        appEl.style.display = state.salerCode ? '' : 'none';
        hintEl.textContent = '';
        if (state.salerCode) {
            loadList(1);
            loadDailyChart();
            loadReconciliationTotals();
            if (state.activeTab === 'shopee') { loadShopeeList(1); }
        }
    }

    // ===== Đối chiếu tổng tiền xuất kho (MISA + Shopee) =====
    function loadReconciliationTotals() {
        if (!state.salerCode) { return; }
        rpc('/misa_sale_status/api/reconciliation_totals', {
            saler_code: state.salerCode, date_from: state.dateFrom, date_to: state.dateTo,
        }).then(function(res) {
            var d = res.data || {};
            document.getElementById('msu-recon-total').textContent = fmtMoney(d.total_actual_amount);
            document.getElementById('msu-recon-misa').textContent = fmtMoney(d.misa_invoiced_amount);
            document.getElementById('msu-recon-shopee').textContent = fmtMoney(d.shopee_invoiced_amount);
            document.getElementById('msu-recon-outstanding').textContent = fmtMoney(d.outstanding_amount);
        }).catch(function(e) { toast('Lỗi tải số liệu đối chiếu: ' + e.message, 'error'); });
    }

    // ===== Tab: Phiếu xuất kho (MISA) / Đơn Shopee / Đơn hải quan =====
    document.querySelectorAll('.msu-tab').forEach(function(btn) {
        btn.addEventListener('click', function() {
            state.activeTab = this.dataset.tab;
            document.querySelectorAll('.msu-tab').forEach(function(b) { b.classList.remove('msu-tab-active'); });
            this.classList.add('msu-tab-active');
            document.getElementById('msu-tab-pickings').style.display = state.activeTab === 'pickings' ? '' : 'none';
            document.getElementById('msu-tab-shopee').style.display = state.activeTab === 'shopee' ? '' : 'none';
            document.getElementById('msu-tab-customs').style.display = state.activeTab === 'customs' ? '' : 'none';
            if (state.activeTab === 'shopee' && !state.shopee.loaded) { loadShopeeList(1); }
            if (state.activeTab === 'customs' && !state.customs.loaded) { loadCustomsList(1); }
        });
    });

    function renderShopeeRows() {
        var tbody = document.getElementById('msu-shopee-tbody');
        tbody.innerHTML = '';
        document.getElementById('msu-shopee-empty').style.display = state.shopee.rows.length ? 'none' : '';
        state.shopee.rows.forEach(function(row) {
            var tr = document.createElement('tr');
            tr.innerHTML =
                '<td><span class="msu-picking-name">' + esc(row.name) + '</span><span class="msu-picking-order">' + esc(row.sale_order_name || '') + '</span></td>' +
                '<td>' + esc(row.partner_name) + '</td>' +
                '<td>' + esc(row.date_done) + '</td>' +
                '<td class="msu-col-num">' + fmtMoney(row.actual_amount) + '</td>' +
                '<td><span class="msu-badge-state msu-badge-state-' + row.state + '">' + esc(row.state_label) + '</span></td>' +
                '<td>' + (row.invoice_no ? esc(row.invoice_no) : '<span class="msu-muted">—</span>') + '</td>' +
                '<td>' + (row.invoice_date ? esc(row.invoice_date) : '<span class="msu-muted">—</span>') + '</td>' +
                '<td class="msu-col-num">' + (row.state === 'accepted' ? fmtMoney(row.invoice_amount) : '<span class="msu-muted">—</span>') + '</td>';
            tbody.appendChild(tr);
        });
    }

    function updateShopeePagination() {
        var totalPages = Math.max(1, Math.ceil(state.shopee.total / PAGE_SIZE));
        var pag = document.getElementById('msu-shopee-pagination');
        pag.style.display = state.shopee.total > PAGE_SIZE ? '' : 'none';
        document.getElementById('msu-shopee-page-label').textContent = 'Trang ' + state.shopee.page + ' / ' + totalPages + ' (' + state.shopee.total + ' đơn)';
        document.getElementById('msu-shopee-prev').disabled = state.shopee.page <= 1;
        document.getElementById('msu-shopee-next').disabled = state.shopee.page >= totalPages;
    }

    function loadShopeeList(page) {
        if (!state.salerCode) { return Promise.resolve(); }
        state.shopee.page = page;
        return rpc('/misa_sale_status/api/shopee_list', {
            saler_code: state.salerCode, search: state.shopee.search, state: state.shopee.stateFilter,
            date_from: state.dateFrom, date_to: state.dateTo,
            limit: PAGE_SIZE, offset: (page - 1) * PAGE_SIZE,
        }).then(function(res) {
            var data = res.data || {};
            state.shopee.rows = data.rows || [];
            state.shopee.total = data.total || 0;
            state.shopee.loaded = true;
            renderShopeeRows();
            updateShopeePagination();
        }).catch(function(e) { toast('Lỗi tải danh sách đơn Shopee: ' + e.message, 'error'); });
    }

    document.getElementById('msu-shopee-search-btn').addEventListener('click', function() {
        state.shopee.search = document.getElementById('msu-shopee-search').value.trim();
        loadShopeeList(1);
    });
    document.getElementById('msu-shopee-search').addEventListener('keydown', function(ev) {
        if (ev.key === 'Enter') { document.getElementById('msu-shopee-search-btn').click(); }
    });
    document.getElementById('msu-shopee-state-select').addEventListener('change', function() {
        state.shopee.stateFilter = this.value;
        loadShopeeList(1);
    });
    document.getElementById('msu-shopee-refresh-btn').addEventListener('click', function() { loadShopeeList(state.shopee.page); });
    document.getElementById('msu-shopee-prev').addEventListener('click', function() { if (state.shopee.page > 1) { loadShopeeList(state.shopee.page - 1); } });
    document.getElementById('msu-shopee-next').addEventListener('click', function() {
        if (state.shopee.page < Math.ceil(state.shopee.total / PAGE_SIZE)) { loadShopeeList(state.shopee.page + 1); }
    });

    // ===== Tab: Đơn hải quan (hóa đơn xuất TRƯỚC khi xuất kho Odoo) =====
    function renderCustomsPreview() {
        var preview = state.customs.preview;
        var section = document.getElementById('msu-customs-preview');
        if (!preview) { section.style.display = 'none'; return; }
        section.style.display = '';
        document.getElementById('msu-customs-preview-no').textContent = preview.invoice_no || '—';
        document.getElementById('msu-customs-preview-refno').textContent = preview.refno_finance || '—';
        document.getElementById('msu-customs-preview-date').textContent = preview.invoice_date ? preview.invoice_date.slice(0, 10) : '—';
        document.getElementById('msu-customs-preview-partner').textContent = preview.partner_name || '—';
        document.getElementById('msu-customs-preview-total').textContent = fmtMoney(preview.total_amount);

        var tbody = document.getElementById('msu-customs-preview-tbody');
        tbody.innerHTML = (preview.lines || []).map(function(line) {
            var orderCell = line.sale_order_found
                ? esc(line.order_code)
                : '<span class="msu-col-diff-bad" title="Không tìm thấy đơn hàng này trong Odoo"><i class="fa fa-warning"></i> ' + esc(line.order_code || '(trống)') + '</span>';
            return '<tr>' +
                '<td>' + orderCell + '</td>' +
                '<td>' + esc(line.inventory_item_code) + '</td>' +
                '<td>' + esc(line.description) + '</td>' +
                '<td class="msu-col-num">' + line.quantity + '</td>' +
                '<td class="msu-col-num">' + fmtMoney(line.unit_price) + '</td>' +
                '<td class="msu-col-num">' + fmtMoney(line.amount) + '</td>' +
                '</tr>';
        }).join('');

        var unmatched = (preview.lines || []).filter(function(l) { return !l.sale_order_found; });
        var warningEl = document.getElementById('msu-customs-preview-warning');
        if (unmatched.length) {
            warningEl.style.display = '';
            warningEl.textContent = 'Có ' + unmatched.length + ' dòng không tìm thấy đơn hàng tương ứng trong Odoo (vẫn ghi nhận được, nhưng cần kiểm tra lại mã đơn).';
        } else {
            warningEl.style.display = 'none';
        }
    }

    document.getElementById('msu-customs-fetch-btn').addEventListener('click', function() {
        var invNo = document.getElementById('msu-customs-inv-input').value.trim();
        if (!invNo) { toast('Vui lòng nhập số hóa đơn.', 'error'); return; }
        var btn = this;
        setBtnLoading(btn, true);
        rpc('/misa_sale_status/api/customs/fetch', { inv_no: invNo }).then(function(res) {
            state.customs.preview = res.preview;
            renderCustomsPreview();
        }).catch(function(e) {
            toast('Lỗi tra cứu hóa đơn: ' + e.message, 'error');
        }).finally(function() { setBtnLoading(btn, false); });
    });

    document.getElementById('msu-customs-cancel-btn').addEventListener('click', function() {
        state.customs.preview = null;
        document.getElementById('msu-customs-inv-input').value = '';
        renderCustomsPreview();
    });

    document.getElementById('msu-customs-save-btn').addEventListener('click', function() {
        if (!state.customs.preview) { return; }
        var invNo = state.customs.preview.invoice_no;
        var btn = this;
        setBtnLoading(btn, true);
        rpc('/misa_sale_status/api/customs/save', { inv_no: invNo }).then(function(res) {
            var matchNote = res.matched_count ? (' (' + res.matched_count + ' dòng đã khớp phiếu xuất kho ngay)') : ' (chưa có phiếu xuất kho nào khớp, sẽ tự thử lại sau)';
            toast('Đã ghi nhận ' + res.count + ' dòng cho hóa đơn ' + res.invoice_no + '.' + matchNote, 'success');
            state.customs.preview = null;
            document.getElementById('msu-customs-inv-input').value = '';
            renderCustomsPreview();
            loadCustomsList(1);
        }).catch(function(e) {
            toast('Lỗi ghi nhận hóa đơn: ' + e.message, 'error');
        }).finally(function() { setBtnLoading(btn, false); });
    });

    // 3 trạng thái hiển thị cho 1 dòng hải quan: matched (xanh) / nomatch (vàng, có
    // đơn hàng nhưng chưa khớp phiếu xuất kho) / noorder (đỏ, không tìm thấy đơn
    // hàng trong Odoo) — dùng chung để tô cả dòng lẫn badge trạng thái.
    function customsRowStatus(row) {
        if (row.match_state === 'matched') { return 'matched'; }
        if (!row.sale_order_found) { return 'noorder'; }
        return 'nomatch';
    }
    function customsRowStatusLabel(row) {
        var s = customsRowStatus(row);
        if (s === 'matched') { return 'Đã khớp phiếu xuất kho'; }
        if (s === 'noorder') { return 'Không tìm thấy đơn hàng'; }
        if (row.match_state === 'partial') { return 'Khớp ' + row.matched_qty + '/' + row.quantity; }
        return 'Chờ xuất kho';
    }
    function customsRowBadgeState(row) {
        var s = customsRowStatus(row);
        if (s === 'matched') { return 'invoiced'; }
        if (s === 'noorder') { return 'missing'; }
        return 'requested';
    }

    function renderCustomsRows() {
        var tbody = document.getElementById('msu-customs-tbody');
        tbody.innerHTML = '';
        document.getElementById('msu-customs-empty').style.display = state.customs.rows.length ? 'none' : '';
        state.customs.rows.forEach(function(row) {
            var tr = document.createElement('tr');
            tr.className = 'msu-row-clickable msu-row-status-' + customsRowStatus(row);
            tr.dataset.id = row.id;
            tr.innerHTML =
                '<td><b>' + esc(row.invoice_no) + '</b></td>' +
                '<td>' + (row.sale_order_found ? esc(row.sale_order_name) : '<i class="fa fa-warning"></i> ' + esc(row.sale_order_name || row.order_code || '(trống)')) + '</td>' +
                '<td><div>' + esc(row.inventory_item_code) + '</div><div class="msu-muted" style="font-size:.78rem">' + esc(row.description) + '</div></td>' +
                '<td class="msu-col-num">' + row.quantity + '</td>' +
                '<td><span class="msu-badge-state msu-badge-state-' + customsRowBadgeState(row) + '" title="' + esc(row.match_note || '') + '">' + esc(customsRowStatusLabel(row)) + '</span></td>';
            tbody.appendChild(tr);
        });
        tbody.querySelectorAll('.msu-row-clickable').forEach(function(tr) {
            tr.addEventListener('click', function() {
                var id = parseInt(this.dataset.id, 10);
                var row = state.customs.rows.find(function(r) { return r.id === id; });
                if (row) { openCustomsDrawer(row); }
            });
        });
    }

    function customsDeleteInvoice(invNo) {
        if (!window.confirm('Xóa toàn bộ dữ liệu đã ghi nhận cho hóa đơn "' + invNo + '"?')) { return; }
        rpc('/misa_sale_status/api/customs/delete', { inv_no: invNo }).then(function() {
            toast('Đã xóa hóa đơn ' + invNo + '.', 'success');
            if (customsDrawerRowId != null) { closeDrawer(); }
            loadCustomsList(state.customs.page);
        }).catch(function(e) { toast('Lỗi xóa: ' + e.message, 'error'); });
    }

    function customsRetryMatch(lineId, btn) {
        setBtnLoading(btn, true);
        rpc('/misa_sale_status/api/customs/retry', { line_id: lineId }).then(function(res) {
            var result = res.result || {};
            if (result.matched) {
                toast('Đã khớp với phiếu ' + result.picking_name + '.', 'success');
            } else {
                toast(result.match_note || 'Vẫn chưa khớp được.', 'warning');
            }
            loadCustomsList(state.customs.page).then(function() {
                if (customsDrawerRowId === lineId) {
                    var updated = state.customs.rows.find(function(r) { return r.id === lineId; });
                    if (updated) { openCustomsDrawer(updated); }
                }
            });
        }).catch(function(e) {
            toast('Lỗi thử khớp lại: ' + e.message, 'error');
            setBtnLoading(btn, false);
        });
    }

    function updateCustomsPagination() {
        var totalPages = Math.max(1, Math.ceil(state.customs.total / PAGE_SIZE));
        var pag = document.getElementById('msu-customs-pagination');
        pag.style.display = state.customs.total > PAGE_SIZE ? '' : 'none';
        document.getElementById('msu-customs-page-label').textContent = 'Trang ' + state.customs.page + ' / ' + totalPages + ' (' + state.customs.total + ' dòng)';
        document.getElementById('msu-customs-prev').disabled = state.customs.page <= 1;
        document.getElementById('msu-customs-next').disabled = state.customs.page >= totalPages;
    }

    function loadCustomsList(page) {
        if (!state.salerCode) { return Promise.resolve(); }
        state.customs.page = page;
        return rpc('/misa_sale_status/api/customs/list', {
            saler_code: state.salerCode, search: state.customs.search, pending_only: state.customs.pendingOnly,
            limit: PAGE_SIZE, offset: (page - 1) * PAGE_SIZE,
        }).then(function(res) {
            var data = res.data || {};
            state.customs.rows = data.rows || [];
            state.customs.total = data.total || 0;
            state.customs.pendingCount = data.pending_count || 0;
            state.customs.loaded = true;
            document.getElementById('msu-customs-pending-count').textContent = state.customs.pendingCount;
            renderCustomsRows();
            updateCustomsPagination();
        }).catch(function(e) { toast('Lỗi tải danh sách đơn hải quan: ' + e.message, 'error'); });
    }

    document.getElementById('msu-customs-search-btn').addEventListener('click', function() {
        state.customs.search = document.getElementById('msu-customs-search').value.trim();
        loadCustomsList(1);
    });
    document.getElementById('msu-customs-search').addEventListener('keydown', function(ev) {
        if (ev.key === 'Enter') { document.getElementById('msu-customs-search-btn').click(); }
    });
    document.getElementById('msu-customs-pending-only').addEventListener('change', function() {
        state.customs.pendingOnly = this.checked;
        loadCustomsList(1);
    });
    document.getElementById('msu-customs-refresh-btn').addEventListener('click', function() { loadCustomsList(state.customs.page); });
    document.getElementById('msu-customs-prev').addEventListener('click', function() { if (state.customs.page > 1) { loadCustomsList(state.customs.page - 1); } });
    document.getElementById('msu-customs-next').addEventListener('click', function() {
        if (state.customs.page < Math.ceil(state.customs.total / PAGE_SIZE)) { loadCustomsList(state.customs.page + 1); }
    });

    selectEl.addEventListener('change', function() {
        state.salerCode = selectEl.value;
        state.selected = {};
        if (state.salerCode) {
            localStorage.setItem(STORAGE_KEY, state.salerCode);
        } else {
            localStorage.removeItem(STORAGE_KEY);
        }
        onSalerChosen();
    });

    function rowMeta(row) {
        var parts = [];
        if (row.multi_order_group) { parts.push('<i class="fa fa-sitemap msu-link-icon" title="Gộp chung nhiều đơn bán: ' + esc(row.group_order_names) + '"></i>'); }
        if (row.master_picking_id || (row.covered_pickings && row.covered_pickings.length)) { parts.push('<i class="fa fa-link msu-link-icon" title="Gộp chung đề nghị xuất HĐ với phiếu khác"></i>'); }
        return parts.join('');
    }

    // Nhóm nút thao tác dùng chung cho bảng (icon-only, size xs) và drawer
    // (có chữ, size sm) — LUÔN hiện đủ 3 nút, disable (không ẩn) nút không áp
    // dụng được để nhóm nút không bị "co lại" trông như mất chức năng.
    function actionButtonsHtml(row, opts) {
        opts = opts || {};
        var size = opts.size || 'xs';
        var withText = !!opts.withText;
        var canModify = row.state !== 'invoiced';
        function label(text) { return withText ? ' ' + text : ''; }
        var checkBtn = '<button class="msu-btn msu-btn-outline-primary msu-btn-' + size + ' msu-act-check" data-id="' + row.id + '" title="Kiểm tra ngay"><i class="fa fa-refresh"></i>' + label('Kiểm tra ngay') + '</button>';
        var linkBtn = '<button class="msu-btn msu-btn-outline-muted msu-btn-' + size + ' msu-act-link" data-id="' + row.id + '" data-name="' + esc(row.name) + '" title="' + (canModify ? 'Gắn mã đề nghị' : 'Đã xuất HĐ, không cần gắn mã đề nghị nữa') + '"' + (canModify ? '' : ' disabled="disabled"') + '><i class="fa fa-pencil"></i>' + label('Gắn mã đề nghị') + '</button>';
        var exceptionBtn = row.exception
            ? '<button class="msu-btn msu-btn-outline-muted msu-btn-' + size + ' msu-act-unexception" data-id="' + row.id + '" title="Bỏ ngoại lệ"><i class="fa fa-undo"></i>' + label('Bỏ ngoại lệ') + '</button>'
            : '<button class="msu-btn msu-btn-outline-danger msu-btn-' + size + ' msu-act-exception" data-id="' + row.id + '" data-name="' + esc(row.name) + '" title="' + (canModify ? 'Đánh dấu ngoại lệ' : 'Đã xuất HĐ, không cần đánh dấu ngoại lệ nữa') + '"' + (canModify ? '' : ' disabled="disabled"') + '><i class="fa fa-ban"></i>' + label('Đánh dấu ngoại lệ') + '</button>';
        return '<div class="msu-btn-group">' + checkBtn + linkBtn + exceptionBtn + '</div>';
    }

    function renderRows() {
        var tbody = document.getElementById('msu-tbody');
        tbody.innerHTML = '';
        document.getElementById('msu-empty').style.display = state.rows.length ? 'none' : '';
        state.rows.forEach(function(row) {
            var tr = document.createElement('tr');
            tr.dataset.id = row.id;
            tr.className = 'msu-row-clickable';
            var checked = state.selected[row.id] ? 'checked="checked"' : '';
            var manualHtml = row.manual_refno
                ? '<span class="msu-manual-refno" title="Đã gắn mã đề nghị thủ công">' + esc(row.manual_refno) + '</span>'
                : '<span class="msu-muted">—</span>';
            var exceptionHtml = row.exception
                ? '<span class="msu-badge-exception" title="' + esc(row.exception_reason || '') + '"><i class="fa fa-ban"></i> Ngoại lệ</span>' : '';
            tr.innerHTML =
                '<td><input type="checkbox" class="msu-row-check" data-id="' + row.id + '" ' + checked + '/></td>' +
                '<td><span class="msu-picking-name">' + esc(row.name) + '</span>' + rowMeta(row) + '<span class="msu-picking-order">' + esc(row.sale_order_name || '') + '</span></td>' +
                '<td>' + esc(row.partner_name) + '</td>' +
                '<td>' + esc(row.date_done) + '</td>' +
                '<td class="msu-col-num">' + fmtMoney(row.actual_amount) + '</td>' +
                '<td><div class="msu-status-cell"><span class="msu-badge-state msu-badge-state-' + row.state + '">' + esc(row.state_label) + '</span>' + exceptionHtml + '</div></td>' +
                '<td>' + manualHtml + '</td>' +
                '<td>' + actionButtonsHtml(row) + '</td>';
            tbody.appendChild(tr);
        });
        bindRowEvents();
        updateBulkBar();
    }

    var lastCounts = {missing: 0, requested: 0, exception: 0, invoiced: 0};

    function updateStats(counts) {
        counts = counts || {};
        lastCounts = counts;
        document.getElementById('msu-count-missing').textContent = counts.missing || 0;
        document.getElementById('msu-count-requested').textContent = counts.requested || 0;
        document.getElementById('msu-count-exception').textContent = counts.exception || 0;
        document.getElementById('msu-count-invoiced').textContent = counts.invoiced || 0;
        renderDonut(counts);
    }

    // ===== Donut chart (cơ cấu trạng thái) — SVG vẽ tay, không cần thư viện =====
    function renderDonut(counts) {
        var container = document.getElementById('msu-donut-container');
        var total = STATE_META.reduce(function(sum, m) { return sum + (counts[m.key] || 0); }, 0);
        if (!total) {
            container.innerHTML = '<div class="msu-empty-chart">Chưa có dữ liệu trong phạm vi đang lọc.</div>';
            return;
        }
        var size = 148, r = 58, cx = size / 2, cy = size / 2, thickness = 20;
        var circumference = 2 * Math.PI * r;
        var gap = 3; // khoảng hở (đơn vị theo chu vi) giữa 2 lát, mô phỏng surface gap
        var offset = 0;
        var segments = [];
        STATE_META.forEach(function(meta) {
            var value = counts[meta.key] || 0;
            if (!value) { return; }
            var len = (value / total) * circumference;
            segments.push({
                meta: meta, value: value,
                dasharray: Math.max(len - gap, 0) + ' ' + (circumference - Math.max(len - gap, 0)),
                dashoffset: -offset,
            });
            offset += len;
        });
        var svgParts = ['<svg class="msu-donut-svg" width="' + size + '" height="' + size + '" viewBox="0 0 ' + size + ' ' + size + '">'];
        svgParts.push('<circle cx="' + cx + '" cy="' + cy + '" r="' + r + '" fill="none" stroke="#f1f0eb" stroke-width="' + thickness + '"/>');
        segments.forEach(function(seg) {
            svgParts.push(
                '<circle cx="' + cx + '" cy="' + cy + '" r="' + r + '" fill="none" stroke="' + COLORS[seg.meta.key] + '" ' +
                'stroke-width="' + thickness + '" stroke-dasharray="' + seg.dasharray + '" stroke-dashoffset="' + seg.dashoffset + '" ' +
                'transform="rotate(-90 ' + cx + ' ' + cy + ')" stroke-linecap="butt">' +
                '<title>' + esc(seg.meta.label) + ': ' + seg.value + ' phiếu</title>' +
                '</circle>'
            );
        });
        svgParts.push('<text x="' + cx + '" y="' + (cy - 4) + '" text-anchor="middle" class="msu-donut-hole-total">' + total + '</text>');
        svgParts.push('<text x="' + cx + '" y="' + (cy + 14) + '" text-anchor="middle" class="msu-donut-hole-label">TỔNG SỐ</text>');
        svgParts.push('</svg>');

        var legendParts = ['<div class="msu-legend">'];
        STATE_META.forEach(function(meta) {
            var value = counts[meta.key] || 0;
            var pct = total ? Math.round((value / total) * 100) : 0;
            legendParts.push(
                '<div class="msu-legend-row">' +
                    '<span class="msu-legend-dot" style="background:' + COLORS[meta.key] + '"></span>' +
                    '<span class="msu-legend-label">' + esc(meta.label) + '</span>' +
                    '<span class="msu-legend-value">' + value + '</span>' +
                    '<span class="msu-muted">(' + pct + '%)</span>' +
                '</div>'
            );
        });
        legendParts.push('</div>');

        container.innerHTML = '<div class="msu-donut-wrap">' + svgParts.join('') + legendParts.join('') + '</div>';
    }

    // ===== Bar + line chart (tiền xuất kho vs tiền đã xuất HĐ theo ngày) =====
    function renderBarChart(buckets) {
        var container = document.getElementById('msu-bar-chart-container');
        if (!buckets || !buckets.length) {
            container.innerHTML = '<div class="msu-empty-chart">Chưa có dữ liệu trong phạm vi đang lọc.</div>';
            return;
        }
        var width = Math.max(container.clientWidth || 560, 320);
        var height = 220;
        var padL = 54, padR = 14, padT = 14, padB = 28;
        var plotW = width - padL - padR, plotH = height - padT - padB;
        var maxVal = 0;
        buckets.forEach(function(b) { maxVal = Math.max(maxVal, b.actual_amount || 0, b.invoice_amount || 0); });
        if (!maxVal) { maxVal = 1; }
        // Làm tròn trục Y lên mốc đẹp (1/2/5 * 10^n) để nhãn dễ đọc.
        var niceMax = (function() {
            var exp = Math.floor(Math.log10(maxVal));
            var base = Math.pow(10, exp);
            var mult = maxVal / base;
            var steps = [1, 2, 2.5, 5, 10];
            for (var i = 0; i < steps.length; i++) { if (mult <= steps[i]) { return steps[i] * base; } }
            return 10 * base;
        })();
        var n = buckets.length;
        var slot = plotW / n;
        var barW = Math.min(24, slot * 0.44);

        function yFor(v) { return padT + plotH - (v / niceMax) * plotH; }
        function xCenter(i) { return padL + slot * i + slot / 2; }

        var ticks = 4;
        var gridParts = [];
        var yLabelParts = [];
        for (var t = 0; t <= ticks; t++) {
            var val = (niceMax / ticks) * t;
            var y = yFor(val);
            gridParts.push('<line x1="' + padL + '" y1="' + y + '" x2="' + (width - padR) + '" y2="' + y + '" stroke="#eceae4" stroke-width="1"/>');
            yLabelParts.push('<text x="' + (padL - 8) + '" y="' + (y + 3) + '" text-anchor="end" font-size="10" fill="#8b8d94">' + fmtCompactMoney(val) + '</text>');
        }

        // Nhãn trục X chọn lọc: ước lượng bề rộng cần cho 1 nhãn rồi chỉ hiện
        // đủ số nhãn vừa khít, tránh chữ đè lên nhau khi có nhiều cột (nhiều
        // tuần/ngày) — luôn hiện nhãn cuối cùng để biết mốc gần nhất.
        var minLabelWidth = 64;
        var maxLabels = Math.max(1, Math.floor(plotW / minLabelWidth));
        var labelStep = Math.max(1, Math.ceil(n / maxLabels));

        var barParts = [], dotParts = [], labelParts = [];
        var linePoints = [];
        buckets.forEach(function(b, i) {
            var cx = xCenter(i);
            var barX = cx - barW / 2;
            var barY = yFor(b.actual_amount || 0);
            var barH = Math.max(padT + plotH - barY, 0);
            if (barH > 0) {
                barParts.push(
                    '<rect x="' + barX + '" y="' + barY + '" width="' + barW + '" height="' + barH + '" rx="4" ry="4" fill="#2a78d6">' +
                    '<title>' + esc(b.label) + ' — Tiền xuất kho: ' + fmtMoney(b.actual_amount) + '</title>' +
                    '</rect>'
                );
            }
            var ly = yFor(b.invoice_amount || 0);
            linePoints.push(cx + ',' + ly);
            dotParts.push(
                '<circle cx="' + cx + '" cy="' + ly + '" r="4" fill="#0ca30c" stroke="#fff" stroke-width="2">' +
                '<title>' + esc(b.label) + ' — Tiền đã xuất HĐ: ' + fmtMoney(b.invoice_amount) + '</title>' +
                '</circle>'
            );
            if (i % labelStep === 0 || i === n - 1) {
                labelParts.push('<text x="' + cx + '" y="' + (height - 8) + '" text-anchor="middle" font-size="9" fill="#8b8d94">' + esc(b.label) + '</text>');
            }
        });

        var svg =
            '<svg width="100%" height="' + height + '" viewBox="0 0 ' + width + ' ' + height + '" preserveAspectRatio="xMidYMid meet">' +
            gridParts.join('') + yLabelParts.join('') +
            '<line x1="' + padL + '" y1="' + (padT + plotH) + '" x2="' + (width - padR) + '" y2="' + (padT + plotH) + '" stroke="#c9c8c1" stroke-width="1"/>' +
            barParts.join('') +
            '<polyline points="' + linePoints.join(' ') + '" fill="none" stroke="#0ca30c" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/>' +
            dotParts.join('') + labelParts.join('') +
            '</svg>';
        container.innerHTML = svg;
    }

    function loadDailyChart() {
        if (!state.salerCode) { return; }
        var weekly = !state.dateFrom && !state.dateTo;
        document.getElementById('msu-chart-subtitle').textContent = weekly
            ? 'Theo tuần (không giới hạn ngày — chọn khoảng ngày để xem theo ngày)'
            : 'Theo ngày, trong khoảng đã chọn';
        rpc('/misa_sale_status/api/daily_stats', {
            saler_code: state.salerCode, date_from: state.dateFrom, date_to: state.dateTo, weekly: weekly,
        }).then(function(res) {
            renderBarChart(res.buckets || []);
        }).catch(function(e) { toast('Lỗi tải biểu đồ theo ngày: ' + e.message, 'error'); });
    }

    function updatePagination() {
        var totalPages = Math.max(1, Math.ceil(state.total / PAGE_SIZE));
        var pag = document.getElementById('msu-pagination');
        pag.style.display = state.total > PAGE_SIZE ? '' : 'none';
        document.getElementById('msu-page-label').textContent = 'Trang ' + state.page + ' / ' + totalPages + ' (' + state.total + ' phiếu)';
        document.getElementById('msu-prev').disabled = state.page <= 1;
        document.getElementById('msu-next').disabled = state.page >= totalPages;
    }

    function loadList(page, opts) {
        opts = opts || {};
        if (!state.salerCode) { return Promise.resolve(); }
        state.page = page;
        return rpc('/misa_sale_status/api/list', {
            saler_code: state.salerCode, search: state.search, state: state.stateFilter,
            date_from: state.dateFrom, date_to: state.dateTo,
            multi_order_group: state.multiOrderGroup, multi_request: state.multiRequest,
            limit: PAGE_SIZE, offset: (page - 1) * PAGE_SIZE,
        }).then(function(res) {
            var data = res.data || {};
            state.rows = data.rows || [];
            state.total = data.total || 0;
            state.selected = {};
            updateStats(data.counts);
            renderRows();
            updatePagination();
            refreshDrawerIfOpen();
        }).catch(function(e) {
            if (!opts.silent) { toast('Lỗi tải danh sách: ' + e.message, 'error'); }
        });
    }

    document.getElementById('msu-search-btn').addEventListener('click', function() {
        state.search = document.getElementById('msu-search').value.trim();
        document.getElementById('msu-search-clear').style.display = state.search ? '' : 'none';
        loadList(1);
    });
    document.getElementById('msu-search').addEventListener('keydown', function(ev) {
        if (ev.key === 'Enter') { document.getElementById('msu-search-btn').click(); }
    });
    document.getElementById('msu-search-clear').addEventListener('click', function() {
        state.search = '';
        document.getElementById('msu-search').value = '';
        this.style.display = 'none';
        loadList(1);
    });
    document.getElementById('msu-state-select').addEventListener('change', function() {
        state.stateFilter = this.value;
        loadList(1);
    });
    document.getElementById('msu-multi-order-group').addEventListener('change', function() {
        state.multiOrderGroup = this.checked;
        loadList(1);
    });
    document.getElementById('msu-multi-request').addEventListener('change', function() {
        state.multiRequest = this.checked;
        loadList(1);
    });
    // Ngày xuất kho là filter DÙNG CHUNG cho cả 2 tab + đối chiếu tổng — đổi 1
    // nơi phải nạp lại cả 3 để số liệu không bị lệch phạm vi với nhau.
    function reloadForDateScopeChange() {
        loadList(1);
        loadDailyChart();
        loadReconciliationTotals();
        if (state.shopee.loaded) { loadShopeeList(1); }
    }
    document.getElementById('msu-date-from').addEventListener('change', function() {
        state.dateFrom = this.value;
        document.getElementById('msu-date-clear').style.display = (state.dateFrom || state.dateTo) ? '' : 'none';
        reloadForDateScopeChange();
    });
    document.getElementById('msu-date-to').addEventListener('change', function() {
        state.dateTo = this.value;
        document.getElementById('msu-date-clear').style.display = (state.dateFrom || state.dateTo) ? '' : 'none';
        reloadForDateScopeChange();
    });
    document.getElementById('msu-date-clear').addEventListener('click', function() {
        state.dateFrom = ''; state.dateTo = '';
        document.getElementById('msu-date-from').value = '';
        document.getElementById('msu-date-to').value = '';
        this.style.display = 'none';
        reloadForDateScopeChange();
    });
    document.getElementById('msu-refresh-btn').addEventListener('click', function() {
        loadList(state.page);
        loadDailyChart();
        loadReconciliationTotals();
    });
    document.getElementById('msu-prev').addEventListener('click', function() { if (state.page > 1) { loadList(state.page - 1); } });
    document.getElementById('msu-next').addEventListener('click', function() {
        if (state.page < Math.ceil(state.total / PAGE_SIZE)) { loadList(state.page + 1); }
    });

    document.getElementById('msu-select-all').addEventListener('change', function() {
        var checked = this.checked;
        state.rows.forEach(function(row) {
            if (checked) { state.selected[row.id] = true; } else { delete state.selected[row.id]; }
        });
        renderRows();
    });

    // Gắn sự kiện cho các nút thao tác trong 1 vùng cụ thể (bảng HOẶC drawer) —
    // scope theo root truyền vào để 2 vùng không đè/nhân đôi listener của nhau
    // dù dùng chung class (actionButtonsHtml dùng chung cho cả 2 nơi).
    function bindActionButtons(root) {
        root.querySelectorAll('.msu-act-check').forEach(function(btn) {
            btn.addEventListener('click', function() { runCheck([parseInt(this.dataset.id, 10)], this); });
        });
        root.querySelectorAll('.msu-act-link').forEach(function(btn) {
            btn.addEventListener('click', function() { openLinkModal(parseInt(this.dataset.id, 10), this.dataset.name); });
        });
        root.querySelectorAll('.msu-act-exception').forEach(function(btn) {
            btn.addEventListener('click', function() { openExceptionModal([parseInt(this.dataset.id, 10)], this.dataset.name); });
        });
        root.querySelectorAll('.msu-act-unexception').forEach(function(btn) {
            btn.addEventListener('click', function() { runUnexception([parseInt(this.dataset.id, 10)], this); });
        });
    }

    function bindRowEvents() {
        var tbody = document.getElementById('msu-tbody');
        tbody.querySelectorAll('.msu-row-check').forEach(function(cb) {
            cb.addEventListener('change', function() {
                var id = parseInt(this.dataset.id, 10);
                if (this.checked) { state.selected[id] = true; } else { delete state.selected[id]; }
                updateBulkBar();
            });
        });
        tbody.querySelectorAll('.msu-row-clickable').forEach(function(tr) {
            tr.addEventListener('click', function(ev) {
                if (ev.target.closest('input, button, .msu-btn, a')) { return; }
                var id = parseInt(this.dataset.id, 10);
                var row = state.rows.find(function(r) { return r.id === id; });
                if (row) { openDrawer(row); }
            });
        });
        bindActionButtons(tbody);
    }

    // ===== Drawer chi tiết (dùng chung 1 khung cho cả "phiếu xuất kho" và
    // "dòng đơn hải quan" — chỉ 1 drawer mở tại 1 thời điểm nên tái dùng DOM,
    // đổi nội dung theo drawerKind) =====
    var drawerOverlay = document.getElementById('msu-drawer-overlay');
    var drawerEl = document.getElementById('msu-drawer');
    var drawerOpenId = null;
    var drawerKind = null; // 'picking' | 'customs'
    var customsDrawerRowId = null;

    function closeDrawer() {
        drawerOverlay.style.display = 'none';
        drawerOpenId = null;
        customsDrawerRowId = null;
        drawerKind = null;
        customsManualState = { open: false, search: '', loading: false, results: [], qty: '' };
    }
    drawerOverlay.addEventListener('click', function(ev) {
        if (ev.target === drawerOverlay) { closeDrawer(); }
    });

    function openDrawer(row) {
        drawerKind = 'picking';
        drawerOpenId = row.id;
        renderDrawerContent(row);
        drawerOverlay.style.display = 'flex';
    }

    function refreshDrawerIfOpen() {
        if (drawerKind !== 'picking' || drawerOpenId == null) { return; }
        var row = state.rows.find(function(r) { return r.id === drawerOpenId; });
        if (row) { renderDrawerContent(row); } else { closeDrawer(); }
    }

    function openCustomsDrawer(row) {
        drawerKind = 'customs';
        customsDrawerRowId = row.id;
        if (!customsManualState.open) {
            customsManualState = { open: false, search: '', loading: false, results: [], qty: '' };
        }
        renderCustomsDrawerContent(row);
        drawerOverlay.style.display = 'flex';
    }

    // Panel "Khớp thủ công" bên trong drawer hải quan — dùng khi hệ thống tự
    // động khớp SAI (chọn nhầm phiếu) hoặc khớp THIẾU (không tìm ra phiếu phù
    // hợp). State module-scope vì drawer được render lại toàn bộ mỗi lần đổi.
    var customsManualState = { open: false, search: '', loading: false, results: [], qty: '' };

    function renderCustomsDrawerContent(row) {
        var matchesHtml = (row.matches && row.matches.length)
            ? '<table class="msu-table" style="margin-top:8px"><thead><tr><th>Phiếu</th><th class="msu-col-num">Số lượng</th><th>Cách khớp</th><th></th></tr></thead><tbody>' +
                row.matches.map(function(m) {
                    return '<tr><td><b>' + esc(m.picking_name) + '</b></td>' +
                        '<td class="msu-col-num">' + m.quantity + '</td>' +
                        '<td>' + (m.is_manual
                            ? '<span class="msu-badge-state msu-badge-state-submitted" title="Người gán: ' + esc(m.matched_by) + '">Thủ công</span>'
                            : '<span class="msu-badge-state msu-badge-state-not_checked">Tự động</span>') + '</td>' +
                        '<td><button class="msu-btn msu-btn-outline-danger msu-btn-xs msu-customs-match-remove" data-match-id="' + m.id + '" title="Xóa lượt khớp này"><i class="fa fa-trash"></i></button></td></tr>';
                }).join('') +
                '</tbody></table>'
            : '<p class="msu-muted" style="font-size:.84rem;margin-top:8px">Chưa khớp phiếu xuất kho nào.</p>';

        drawerEl.innerHTML =
            '<div class="msu-drawer-header">' +
                '<div><h4 class="msu-drawer-title">' + esc(row.invoice_no) + '</h4><div class="msu-drawer-subtitle">' + esc(row.partner_name) + '</div></div>' +
                '<button class="msu-drawer-close" id="msu-drawer-close-btn"><i class="fa fa-times"></i></button>' +
            '</div>' +
            '<div class="msu-drawer-body">' +
                '<div class="msu-drawer-section">' +
                    '<div class="msu-drawer-meta">' +
                        '<div class="msu-drawer-meta-item"><span class="msu-meta-label">Trạng thái</span><span class="msu-badge-state msu-badge-state-' + customsRowBadgeState(row) + '">' + esc(customsRowStatusLabel(row)) + '</span></div>' +
                        (row.match_note ? '<div class="msu-drawer-meta-item"><span class="msu-meta-label">Ghi chú khớp</span><span class="msu-meta-value">' + esc(row.match_note) + '</span></div>' : '') +
                        '<div class="msu-drawer-meta-item"><span class="msu-meta-label">Số chứng từ</span><span class="msu-meta-value">' + (row.refno_finance ? esc(row.refno_finance) : '—') + '</span></div>' +
                        '<div class="msu-drawer-meta-item"><span class="msu-meta-label">Ngày hóa đơn</span><span class="msu-meta-value">' + esc(row.invoice_date) + '</span></div>' +
                        '<div class="msu-drawer-meta-item"><span class="msu-meta-label">Đơn hàng</span><span class="msu-meta-value' + (row.sale_order_found ? '' : ' msu-col-diff-bad') + '">' + esc(row.sale_order_name || row.order_code || '—') + '</span></div>' +
                        '<div class="msu-drawer-meta-item"><span class="msu-meta-label">Mã hàng</span><span class="msu-meta-value">' + esc(row.inventory_item_code) + '</span></div>' +
                        '<div class="msu-drawer-meta-item"><span class="msu-meta-label">Tên hàng</span><span class="msu-meta-value">' + esc(row.description) + '</span></div>' +
                        '<div class="msu-drawer-meta-item"><span class="msu-meta-label">Số lượng hóa đơn</span><span class="msu-meta-value">' + row.quantity + '</span></div>' +
                        (row.match_state !== 'matched' ? '<div class="msu-drawer-meta-item"><span class="msu-meta-label">Còn thiếu</span><span class="msu-meta-value msu-col-diff-bad">' + row.remaining_qty + '</span></div>' : '') +
                        '<div class="msu-drawer-meta-item"><span class="msu-meta-label">Đơn giá</span><span class="msu-meta-value">' + fmtMoney(row.unit_price) + '</span></div>' +
                        '<div class="msu-drawer-meta-item"><span class="msu-meta-label">Thành tiền</span><span class="msu-meta-value">' + fmtMoney(row.amount) + '</span></div>' +
                        '<div class="msu-drawer-meta-item"><span class="msu-meta-label">Ghi nhận bởi</span><span class="msu-meta-value">' + esc(row.fetched_by) + '</span></div>' +
                    '</div>' +
                '</div>' +
                '<div class="msu-drawer-section">' +
                    '<p class="msu-drawer-section-title">Phiếu xuất kho đã khớp</p>' +
                    matchesHtml +
                '</div>' +
                '<div class="msu-drawer-section" id="msu-customs-manual-panel"></div>' +
            '</div>' +
            '<div class="msu-drawer-actions" id="msu-customs-drawer-actions"></div>';

        document.getElementById('msu-drawer-close-btn').addEventListener('click', closeDrawer);
        drawerEl.querySelectorAll('.msu-customs-match-remove').forEach(function(btn) {
            btn.addEventListener('click', function() {
                removeCustomsMatchRow(parseInt(this.dataset.matchId, 10), row);
            });
        });
        renderCustomsDrawerActions(row);
        renderCustomsManualPanel(row);
    }

    function renderCustomsDrawerActions(row) {
        var actionsEl = document.getElementById('msu-customs-drawer-actions');
        if (!actionsEl) { return; }
        if (customsManualState.open) { actionsEl.innerHTML = ''; return; }
        actionsEl.innerHTML =
            (row.match_state !== 'matched' ? '<button class="msu-btn msu-btn-outline-primary msu-btn-sm" id="msu-customs-drawer-retry"><i class="fa fa-refresh"></i> Thử khớp lại</button>' : '') +
            (row.match_state !== 'matched' ? '<button class="msu-btn msu-btn-outline-muted msu-btn-sm" id="msu-customs-drawer-manual"><i class="fa fa-hand-pointer-o"></i> Khớp thủ công</button>' : '') +
            '<button class="msu-btn msu-btn-outline-danger msu-btn-sm" id="msu-customs-drawer-delete"><i class="fa fa-trash"></i> Xóa cả hóa đơn này</button>';
        var retryBtn = document.getElementById('msu-customs-drawer-retry');
        if (retryBtn) {
            retryBtn.addEventListener('click', function() { customsRetryMatch(row.id, retryBtn); });
        }
        var manualBtn = document.getElementById('msu-customs-drawer-manual');
        if (manualBtn) {
            manualBtn.addEventListener('click', function() { openCustomsManualPanel(row); });
        }
        document.getElementById('msu-customs-drawer-delete').addEventListener('click', function() {
            customsDeleteInvoice(row.invoice_no);
        });
    }

    function openCustomsManualPanel(row) {
        customsManualState = { open: true, search: '', loading: false, results: [], qty: String(row.remaining_qty) };
        renderCustomsManualPanel(row);
        renderCustomsDrawerActions(row);
        searchCustomsManualCandidates(row);
    }

    function closeCustomsManualPanel(row) {
        customsManualState = { open: false, search: '', loading: false, results: [], qty: '' };
        renderCustomsManualPanel(row);
        renderCustomsDrawerActions(row);
    }

    function renderCustomsManualPanel(row) {
        var panel = document.getElementById('msu-customs-manual-panel');
        if (!panel) { return; }
        if (!customsManualState.open) { panel.innerHTML = ''; return; }
        var resultsHtml;
        if (customsManualState.loading) {
            resultsHtml = '<p class="msu-muted" style="font-size:.84rem"><i class="fa fa-spinner fa-spin"></i> Đang tìm...</p>';
        } else if (customsManualState.results.length) {
            resultsHtml = '<table class="msu-table" style="margin-top:8px"><thead><tr><th>Phiếu</th><th>Trạng thái</th><th class="msu-col-num">Đã xuất (mã hàng này)</th><th></th></tr></thead><tbody>' +
                customsManualState.results.map(function(p) {
                    return '<tr><td><b>' + esc(p.name) + '</b></td>' +
                        '<td>' + esc(p.state_label) + '</td>' +
                        '<td class="msu-col-num">' + p.shipped_qty + (p.already_matched_qty ? ' <span class="msu-muted">(đã dùng ' + p.already_matched_qty + ')</span>' : '') + '</td>' +
                        '<td><button class="msu-btn msu-btn-primary msu-btn-xs msu-customs-manual-pick" data-picking-id="' + p.id + '">Gán</button></td></tr>';
                }).join('') +
                '</tbody></table>';
        } else {
            resultsHtml = '<p class="msu-muted" style="font-size:.84rem">Không tìm thấy phiếu nào phù hợp.</p>';
        }
        panel.innerHTML =
            '<p class="msu-drawer-section-title">Chọn phiếu khớp thủ công</p>' +
            '<div style="display:flex;gap:8px;flex-wrap:wrap">' +
                '<input type="text" id="msu-customs-manual-search" class="msu-input" style="flex:1;min-width:160px" placeholder="Tìm theo tên phiếu (bỏ trống = phiếu của đúng đơn hàng)" value="' + esc(customsManualState.search) + '"/>' +
                '<button class="msu-btn msu-btn-primary msu-btn-sm" id="msu-customs-manual-search-btn">Tìm</button>' +
            '</div>' +
            '<div style="margin-top:8px"><label class="msu-meta-label" style="display:block;margin-bottom:3px">Số lượng gán</label>' +
                '<input type="number" step="any" id="msu-customs-manual-qty" class="msu-input" style="max-width:120px" value="' + esc(customsManualState.qty) + '"/>' +
            '</div>' +
            resultsHtml +
            '<div style="margin-top:10px"><button class="msu-btn msu-btn-outline-muted msu-btn-sm" id="msu-customs-manual-close">Đóng</button></div>';

        document.getElementById('msu-customs-manual-search-btn').addEventListener('click', function() {
            customsManualState.search = document.getElementById('msu-customs-manual-search').value.trim();
            searchCustomsManualCandidates(row);
        });
        document.getElementById('msu-customs-manual-search').addEventListener('keydown', function(ev) {
            if (ev.key === 'Enter') { document.getElementById('msu-customs-manual-search-btn').click(); }
        });
        document.getElementById('msu-customs-manual-qty').addEventListener('input', function() {
            customsManualState.qty = this.value;
        });
        document.getElementById('msu-customs-manual-close').addEventListener('click', function() {
            closeCustomsManualPanel(row);
        });
        panel.querySelectorAll('.msu-customs-manual-pick').forEach(function(btn) {
            btn.addEventListener('click', function() {
                pickCustomsManualPicking(row, parseInt(this.dataset.pickingId, 10));
            });
        });
    }

    function searchCustomsManualCandidates(row) {
        customsManualState.loading = true;
        renderCustomsManualPanel(row);
        rpc('/misa_sale_status/api/customs/search_pickings', { line_id: row.id, search: customsManualState.search || false }).then(function(res) {
            customsManualState.loading = false;
            customsManualState.results = res.rows || [];
            renderCustomsManualPanel(row);
        }).catch(function(e) {
            customsManualState.loading = false;
            renderCustomsManualPanel(row);
            toast('Lỗi tìm phiếu: ' + e.message, 'error');
        });
    }

    function pickCustomsManualPicking(row, pickingId) {
        rpc('/misa_sale_status/api/customs/manual_match', {
            line_id: row.id, picking_id: pickingId, quantity: customsManualState.qty || false,
        }).then(function(res) {
            var result = res.result || {};
            toast('Đã gán phiếu ' + result.picking_name + ' (thủ công).', 'success');
            closeCustomsManualPanel(row);
            loadCustomsList(state.customs.page).then(function() {
                if (customsDrawerRowId === row.id) {
                    var updated = state.customs.rows.find(function(r) { return r.id === row.id; });
                    if (updated) { openCustomsDrawer(updated); }
                }
            });
        }).catch(function(e) { toast('Lỗi gán thủ công: ' + e.message, 'error'); });
    }

    function removeCustomsMatchRow(matchId, row) {
        if (!window.confirm('Xóa lượt khớp này? Phiếu xuất kho liên quan có thể quay lại trạng thái chưa xuất hóa đơn.')) { return; }
        rpc('/misa_sale_status/api/customs/remove_match', { match_id: matchId }).then(function() {
            toast('Đã xóa lượt khớp.', 'success');
            loadCustomsList(state.customs.page).then(function() {
                if (customsDrawerRowId === row.id) {
                    var updated = state.customs.rows.find(function(r) { return r.id === row.id; });
                    if (updated) { openCustomsDrawer(updated); }
                }
            });
        }).catch(function(e) { toast('Lỗi xóa lượt khớp: ' + e.message, 'error'); });
    }

    function renderDrawerContent(row) {
        var exceptionHtml = row.exception
            ? '<div class="msu-drawer-section"><p class="msu-drawer-section-title">Ngoại lệ</p><div class="msu-drawer-reason">' + esc(row.exception_reason || '') + '</div></div>'
            : '';
        var groupItems = [];
        if (row.master_picking_name) {
            groupItems.push('<div class="msu-drawer-list-item"><span>Phiếu gốc</span><b>' + esc(row.master_picking_name) + '</b></div>');
        }
        if (row.covered_pickings && row.covered_pickings.length) {
            groupItems.push('<div class="msu-drawer-list-item"><span>Phiếu đi kèm</span><b>' + esc(row.covered_pickings.map(function(c) { return c.name; }).join(', ')) + '</b></div>');
        }
        if (row.multi_order_group && row.group_order_names) {
            groupItems.push('<div class="msu-drawer-list-item"><span>Đơn bán trong nhóm gộp</span><b>' + esc(row.group_order_names) + '</b></div>');
        }
        var groupHtml = groupItems.length
            ? '<div class="msu-drawer-section"><p class="msu-drawer-section-title">Gộp chung đề nghị xuất HĐ</p><div class="msu-drawer-list">' + groupItems.join('') + '</div></div>'
            : '';
        var siblingsHtml = row.sale_order_name
            ? '<div class="msu-drawer-section" id="msu-drawer-siblings-section"><p class="msu-drawer-section-title">Phiếu xuất kho khác cùng đơn hàng</p><div class="msu-drawer-list" id="msu-drawer-siblings-list"><span class="msu-muted">Đang tải...</span></div></div>'
            : '';
        var diffClass = row.amount_mismatch ? ' msu-col-diff-bad' : '';

        drawerEl.innerHTML =
            '<div class="msu-drawer-header">' +
                '<div><h4 class="msu-drawer-title">' + esc(row.name) + '</h4><div class="msu-drawer-subtitle">' + esc(row.partner_name) + '</div></div>' +
                '<button class="msu-drawer-close" id="msu-drawer-close-btn"><i class="fa fa-times"></i></button>' +
            '</div>' +
            '<div class="msu-drawer-body">' +
                '<div class="msu-drawer-section">' +
                    '<div class="msu-drawer-meta">' +
                        '<div class="msu-drawer-meta-item"><span class="msu-meta-label">Đơn hàng</span><span class="msu-meta-value">' + (row.sale_order_name ? esc(row.sale_order_name) : '—') + '</span></div>' +
                        '<div class="msu-drawer-meta-item"><span class="msu-meta-label">Ngày xuất kho</span><span class="msu-meta-value">' + esc(row.date_done) + '</span></div>' +
                        '<div class="msu-drawer-meta-item"><span class="msu-meta-label">Trạng thái</span><span class="msu-badge-state msu-badge-state-' + row.state + '">' + esc(row.state_label) + '</span></div>' +
                        '<div class="msu-drawer-meta-item"><span class="msu-meta-label">Tiền thực xuất</span><span class="msu-meta-value">' + fmtMoney(row.actual_amount) + '</span></div>' +
                        '<div class="msu-drawer-meta-item"><span class="msu-meta-label">Số hóa đơn</span><span class="msu-meta-value">' + (row.invoice_no ? esc(row.invoice_no) : '—') + '</span></div>' +
                        '<div class="msu-drawer-meta-item"><span class="msu-meta-label">Tiền hóa đơn</span><span class="msu-meta-value">' + (row.state === 'invoiced' ? fmtMoney(row.invoice_amount) : '—') + '</span></div>' +
                        '<div class="msu-drawer-meta-item"><span class="msu-meta-label">Chênh lệch tiền</span><span class="msu-meta-value' + diffClass + '">' + (row.state === 'invoiced' ? fmtMoney(row.amount_diff) : '—') + '</span></div>' +
                        '<div class="msu-drawer-meta-item"><span class="msu-meta-label">Mã đề nghị (gắn tay)</span><span class="msu-meta-value">' + (row.manual_refno ? esc(row.manual_refno) : '—') + '</span></div>' +
                    '</div>' +
                '</div>' +
                groupHtml + siblingsHtml + exceptionHtml +
            '</div>' +
            '<div class="msu-drawer-actions">' + actionButtonsHtml(row, {size: 'sm', withText: true}) + '</div>';

        document.getElementById('msu-drawer-close-btn').addEventListener('click', closeDrawer);
        bindActionButtons(drawerEl);
        if (row.sale_order_name) { loadSiblings(row.id); }
    }

    // Phiếu xuất kho khác cùng đơn hàng (1 đơn giao/xuất nhiều đợt) — tải
    // riêng (không nằm sẵn trong row) vì chỉ cần khi mở drawer, tránh tốn
    // thêm 1 truy vấn cho MỌI dòng trong danh sách.
    function loadSiblings(pickingId) {
        rpc('/misa_sale_status/api/picking_siblings', {picking_id: pickingId, saler_code: state.salerCode}).then(function(res) {
            if (drawerOpenId !== pickingId) { return; }
            var container = document.getElementById('msu-drawer-siblings-list');
            if (!container) { return; }
            var siblings = res.siblings || [];
            if (!siblings.length) {
                container.innerHTML = '<span class="msu-muted">Không có phiếu nào khác.</span>';
                return;
            }
            container.innerHTML = siblings.map(function(s) {
                return '<div class="msu-drawer-list-item msu-drawer-sibling" data-id="' + s.id + '">' +
                    '<span>' + esc(s.name) + ' <span class="msu-muted">(' + esc(s.date_done) + ')</span></span>' +
                    '<span class="msu-badge-state msu-badge-state-' + s.state + '">' + esc(s.state_label) + '</span>' +
                    '</div>';
            }).join('');
            container.querySelectorAll('.msu-drawer-sibling').forEach(function(el) {
                el.addEventListener('click', function() { openSiblingDrawer(parseInt(this.dataset.id, 10)); });
            });
        }).catch(function() {
            var container = document.getElementById('msu-drawer-siblings-list');
            if (container) { container.innerHTML = '<span class="msu-muted">Lỗi tải dữ liệu.</span>'; }
        });
    }

    function openSiblingDrawer(pickingId) {
        rpc('/misa_sale_status/api/picking_row', {picking_id: pickingId, saler_code: state.salerCode}).then(function(res) {
            if (res.row) { openDrawer(res.row); }
        }).catch(function(e) { toast('Lỗi mở phiếu: ' + e.message, 'error'); });
    }

    function updateBulkBar() {
        var ids = Object.keys(state.selected).map(Number);
        var bar = document.getElementById('msu-bulk-bar');
        bar.style.display = ids.length ? '' : 'none';
        document.getElementById('msu-bulk-count').textContent = 'Đã chọn ' + ids.length + ' phiếu';
    }

    function runCheck(ids, btn) {
        setBtnLoading(btn, true);
        return rpc('/misa_sale_status/api/check', {picking_ids: ids, saler_code: state.salerCode}).then(function() {
            toast('Đã kiểm tra xong ' + ids.length + ' phiếu.', 'success');
            return loadList(state.page);
        }).then(function() {
            loadDailyChart();
            loadReconciliationTotals();
        }).catch(function(e) {
            toast('Lỗi kiểm tra MISA: ' + e.message, 'error');
        }).finally(function() { setBtnLoading(btn, false); });
    }
    function runUnexception(ids, btn) {
        setBtnLoading(btn, true);
        return rpc('/misa_sale_status/api/unmark_exception', {picking_ids: ids, saler_code: state.salerCode}).then(function() {
            toast('Đã bỏ đánh dấu ngoại lệ.', 'success');
            return loadList(state.page);
        }).catch(function(e) {
            toast('Lỗi: ' + e.message, 'error');
        }).finally(function() { setBtnLoading(btn, false); });
    }

    document.getElementById('msu-bulk-check').addEventListener('click', function() { runCheck(Object.keys(state.selected).map(Number), this); });
    document.getElementById('msu-bulk-unexception').addEventListener('click', function() { runUnexception(Object.keys(state.selected).map(Number), this); });
    document.getElementById('msu-bulk-exception').addEventListener('click', function() {
        openExceptionModal(Object.keys(state.selected).map(Number), Object.keys(state.selected).length + ' phiếu đã chọn');
    });

    // ===== Modal: gắn mã đề nghị =====
    var linkModal = document.getElementById('msu-link-modal');
    var linkPickingId = null;
    function openLinkModal(id, name) {
        linkPickingId = id;
        document.getElementById('msu-link-picking-name').textContent = name;
        document.getElementById('msu-link-refno').value = '';
        document.getElementById('msu-link-error').textContent = '';
        linkModal.style.display = 'flex';
    }
    document.getElementById('msu-link-cancel').addEventListener('click', function() { linkModal.style.display = 'none'; });
    document.getElementById('msu-link-confirm').addEventListener('click', function() {
        var refno = document.getElementById('msu-link-refno').value.trim();
        var errEl = document.getElementById('msu-link-error');
        if (!refno) { errEl.textContent = 'Vui lòng nhập mã đề nghị.'; return; }
        var btn = this;
        setBtnLoading(btn, true);
        rpc('/misa_sale_status/api/manual_link', {picking_id: linkPickingId, saler_code: state.salerCode, refno: refno}).then(function(res) {
            linkModal.style.display = 'none';
            if (res.warning) { toast(res.warning, 'warning'); } else { toast('Đã gắn mã đề nghị và xác nhận đã xuất hóa đơn.', 'success'); }
            loadList(state.page);
            loadDailyChart();
            loadReconciliationTotals();
        }).catch(function(e) { errEl.textContent = e.message; }).finally(function() { setBtnLoading(btn, false); });
    });

    // ===== Modal: đánh dấu ngoại lệ =====
    var exceptionModal = document.getElementById('msu-exception-modal');
    var exceptionIds = [];
    function openExceptionModal(ids, label) {
        exceptionIds = ids;
        document.getElementById('msu-exception-target').textContent = 'Phiếu: ' + label;
        document.getElementById('msu-exception-reason').value = '';
        document.getElementById('msu-exception-error').textContent = '';
        exceptionModal.style.display = 'flex';
    }
    document.getElementById('msu-exception-cancel').addEventListener('click', function() { exceptionModal.style.display = 'none'; });
    document.getElementById('msu-exception-confirm').addEventListener('click', function() {
        var reason = document.getElementById('msu-exception-reason').value.trim();
        var errEl = document.getElementById('msu-exception-error');
        if (!reason) { errEl.textContent = 'Vui lòng nhập lý do.'; return; }
        var btn = this;
        setBtnLoading(btn, true);
        rpc('/misa_sale_status/api/mark_exception', {picking_ids: exceptionIds, saler_code: state.salerCode, reason: reason}).then(function() {
            exceptionModal.style.display = 'none';
            toast('Đã đánh dấu ngoại lệ.', 'success');
            loadList(state.page);
        }).catch(function(e) { errEl.textContent = e.message; }).finally(function() { setBtnLoading(btn, false); });
    });

    window.addEventListener('resize', function() {
        if (state.salerCode) { loadDailyChart(); }
    });

    loadSalerCodes();
    // Cảnh báo trong trang: tự làm mới định kỳ để badge/đếm luôn cập nhật kể cả
    // khi sale không thao tác gì (đóng vai trò "cảnh báo" theo yêu cầu, không
    // cần push notification trình duyệt).
    setInterval(function() {
        if (state.salerCode) { loadList(state.page, {silent: true}); }
    }, 60000);
})();
